/* Pure 05/07 view. No model, persistence, network, authority or event ownership. */
(function(g){'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=x=>Array.isArray(x)?x:[];
const valid=n=>Number.isSafeInteger(n)&&n>=0;
const money=n=>valid(n)?'¥'+Math.floor(n/100)+'.'+String(n%100).padStart(2,'0'):'金额待核对';
const count=n=>valid(n)?String(n):'待核对';
const statuses={pending:'待模拟支付',paid:'待模拟发货',shipped:'待演示收货',completed:'已模拟完成',cancelled:'已取消',refunded:'已模拟退款'};
const notice='<aside class="ccg-notice" role="note"><b>合成商城示例 · 非真实交易</b><span>订单、库存、价格和配送均为本机演示；无真实付款、发货或售后服务。请勿填写真实个人资料。</span></aside>';
function button(text,action,id,o,kind='secondary',disabled=false){return `<button type="button" class="ccg-button ccg-${kind}" data-action="${esc(action)}" data-view="${esc(o.renderToken)}" data-id="${esc(id)}"${disabled?' disabled aria-disabled="true" data-ccg-disabled="true"':''}>${esc(text)}</button>`;}
function picture(p,o){
 const sku=o.productImages?.[String(p.id)],category=o.categoryImages?.[p.category];
 const image=typeof sku==='string'&&/^images\/commerce\/products\/sku-[0-9]+-original-v[0-9]+\.png$/.test(sku)?sku:typeof category==='string'&&/^images\/commerce\/[a-z0-9-]+\.(png|svg|webp)$/.test(category)?category:'';
 return `<figure class="ccg-picture" data-ccg-image-state="${image?'loading':'missing'}"><div class="ccg-picture-frame"><span class="ccg-image-fallback"><span aria-hidden="true">◇</span><small>${image?'商品图加载中':'暂无可用商品演示图'}</small></span>${image?`<img data-ccg-product-image src="${esc(image)}" alt="${esc(p.name)} · 原创演示图，非实物照" aria-hidden="true" loading="lazy" decoding="async">`:''}</div><figcaption>${image?'加载后为原创演示图 · 非实物照':'不推测商品外观'}</figcaption></figure>`;
}
function canAdd(p,s){const qty=list(s.cart).find(i=>i.id===p.id)?.qty??0;return p.listed===true&&p.status==='approved'&&valid(p.priceCents)&&valid(p.stock)&&valid(qty)&&qty<p.stock;}
function totalQty(items){let n=0;for(const i of list(items)){if(!valid(i.qty)||!valid(n+i.qty))return null;n+=i.qty;}return n;}
function shopIcon(name){
 const paths={cart:'<path d="M3 4h2l3 12h11l2-9H6M10 20h.01M18 20h.01"/>',all:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/>',category:'<path d="M9 3h6v4H9zM8 7h8l2 4v9H6v-9zM9 13h6M12 10v6"/>'};
 return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+paths[name]+'</svg>';
}
function shopAdd(p,s,o){const allowed=canAdd(p,s),label=allowed?'加入1件演示购物车':'当前商品暂不可加入';return `<button type="button" class="ccg-button ccg-primary ccg05-add" data-action="add" data-view="${esc(o.renderToken)}" data-id="${esc(p.id)}" aria-label="${esc(label+'：'+p.name)}"${allowed?'':' disabled aria-disabled="true" data-ccg-disabled="true"'}>${shopIcon('cart')}<span class="ccg05-sr-only">${label}</span></button>`;}
function renderShop(s,o={}){
 const products=list(s.products),detail=products.find(p=>p.id===o.detail);if(detail)return renderDetail(s,detail,o);
 const category=o.category||'全部',search=String(o.search||''),available=products.filter(p=>p.listed===true&&p.status==='approved');
 const categories=['全部',...new Set(available.map(p=>String(p.category||'未分类')))];
 const shown=available.filter(p=>(category==='全部'||p.category===category)&&String(p.name||'').toLowerCase().includes(search.trim().toLowerCase()));
 return `<section class="ccg ccg-catalog ccg05-catalog" data-ccg-view="catalog"><header class="ccg05-heading"><div><h1>营养生活商城</h1><p>认真挑选，每一份营养。</p></div><label class="ccg-search"><span class="ccg05-sr-only">搜索商品</span><input id="product-search" type="search" value="${esc(search)}" placeholder="搜索商品" autocomplete="off"></label></header><div class="ccg05-tools"><a class="ccg-link" href="#cart">${shopIcon('cart')}<span>购物车 · ${count(totalQty(s.cart))}</span></a><a class="ccg-link" href="orders.html">订单</a><a class="ccg-link" href="settings.html">说明</a><div data-nutri-feedback-slot aria-label="界面音效设置"></div></div><div class="ccg-categories" aria-label="商品分类">${categories.map((c,i)=>`<button type="button" class="ccg-category ccg05-category" data-action="category" data-view="${esc(o.renderToken)}" data-id="${esc(c)}" aria-pressed="${c===category}"><span class="ccg05-category-icon ccg05-tone-${i%4}">${shopIcon(c==='全部'?'all':'category')}</span><span>${esc(c)}</span></button>`).join('')}</div>${notice.replace('非真实交易</b>','非真实交易 · AI 未连接</b>')}<div class="ccg-section-heading"><h2>自选商品</h2><span>${shown.length} 款 · 当前合成目录</span></div><div class="ccg-products">${shown.map(p=>`<article class="ccg-card ccg-product ccg05-product">${picture(p,o)}<div class="ccg-product-copy"><h3>${esc(p.name)}</h3><p>${esc(p.spec||'规格待核验')}</p><p class="ccg-muted">演示库存 ${count(p.stock)} 件</p><div class="ccg05-product-bottom"><strong class="ccg-price">${money(p.priceCents)}<small>演示价</small></strong>${shopAdd(p,s,o)}</div>${button('查看商品资料 ›','detail',p.id,o)}</div></article>`).join('')||'<div class="ccg-card ccg-empty"><h3>没有匹配商品</h3><p>试试其他分类或关键词。未上架、未审核通过的商品不会列出。</p></div>'}</div><p class="ccg-footnote">商品名称、规格与价格来自当前模型资料；不生成销量、购买评价或功效承诺。演示图不代表真实包装或配料。</p></section>`;
}
function renderDetail(s,p,o){
 const fields=[['类别',p.category],['生产商',p.manufacturer],['商品资质',p.qualification],['保质期',p.shelfLife]];
 return `<section class="ccg ccg-detail ccg05-detail" data-ccg-view="detail"><header class="ccg-detail-head">${button('‹ 返回商品列表','close','',o)}<a href="#cart" data-action="close" data-view="${esc(o.renderToken)}">${shopIcon('cart')}<span>购物车 ${count(totalQty(s.cart))}</span></a></header><div class="ccg05-detail-media">${picture(p,o)}</div><article class="ccg-card ccg05-detail-summary"><div class="ccg-section-heading"><h1>${esc(p.name)}</h1><strong class="ccg-price">${money(p.priceCents)}</strong></div><p>${esc(p.description||'商品说明待补充')}</p><div class="ccg05-real-facts"><div><span>原规格</span><strong>${esc(p.spec||'待核验')}</strong></div><div><span>演示库存</span><strong>${count(p.stock)} 件</strong></div><div><span>当前状态</span><strong>${p.listed?'演示上架':'已下架'} · ${p.status==='approved'?'演示审核通过':'待审核或未通过'}</strong></div></div></article>${notice}<section class="ccg-card ccg05-ingredients"><h2>配料资料</h2><p>${esc(p.ingredients||'当前商品资料未提供配料表，待商家核验。')}</p><p class="ccg-muted">商品图中的装饰与包装不作为配料依据。</p></section><section class="ccg-card ccg05-nutrition"><h2>营养标签</h2><p>当前目录没有可核验的营养标签数据；本页不按规格或图片推算营养成分、剂量或疗效。</p></section><section class="ccg-card ccg05-source"><h2>商品资料与来源</h2><dl class="ccg-facts">${fields.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'待核验')}</dd></div>`).join('')}</dl><details><summary>来源、评价与真实销售边界</summary><p>资料来源：${esc(p.source||'当前模型商品资料；具体来源待核验')}。</p><p>没有真实购买评价；不生成销量、好评或疗效。真实销售所需标签、资质和审核仍待核验。</p></details></section><div class="ccg-detail-actions">${button(canAdd(p,s)?'加入1件演示车':'暂不可加入','add',p.id,o,'primary',!canAdd(p,s))}<a class="ccg-link" href="#cart" data-action="close" data-view="${esc(o.renderToken)}">去核对演示订单 ›</a></div></section>`;
}
function orderCounts(s){const orders=list(s.orders),counts={all:orders.length};for(const status of Object.keys(statuses))counts[status]=orders.filter(o=>o.status===status).length;counts.unknown=orders.filter(o=>!Object.hasOwn(statuses,o.status)).length;return counts;}
function renderOrders(s,o={}){const orders=list(s.orders),counts=orderCounts(s),filter=Object.hasOwn(counts,o.filter)?o.filter:'all',shown=orders.filter(x=>filter==='all'||(filter==='unknown'?!Object.hasOwn(statuses,x.status):x.status===filter));const tabs=[['all','全部'],...Object.entries(statuses),...(counts.unknown?[['unknown','状态待核对']]:[])];return `<section class="ccg ccg-orders" data-ccg-view="orders"><header class="ccg-detail-head"><a href="shop.html">‹ 返回商城</a><h1>我的演示订单</h1></header>${notice}<div class="ccg-order-filters" role="group" aria-label="订单状态筛选">${tabs.map(([key,label])=>`<button type="button" data-order-filter="${key}" data-view="${esc(o.renderToken)}" aria-pressed="${filter===key}">${label} <b>${counts[key]}</b></button>`).join('')}</div><p class="ccg-muted">显示 ${shown.length} / ${orders.length} 笔，数量和状态来自同一订单快照。</p><div class="ccg-order-list">${shown.map(order=>renderOrder(s,order,o)).join('')||`<div class="ccg-card ccg-empty"><h2>${orders.length?'此状态下暂无订单':'还没有演示订单'}</h2><p>不会生成虚构购买记录填满列表。</p><a href="shop.html">去商城查看商品 →</a></div>`}</div><p class="ccg-footnote">此页只呈现用户的本机合成订单。不代表真实售后受理、商家审核权限或配送承诺。</p></section>`;}
function renderOrder(s,order,o){const status=Object.hasOwn(statuses,order.status)?statuses[order.status]:'状态待核对';const actions=order.status==='pending'?button('取消演示订单','cancelled',order.id,o)+button('模拟支付','paid',order.id,o,'primary'):order.status==='shipped'?button('确认演示收货','completed',order.id,o,'primary'):'';return `<article class="ccg-card ccg-order"><div class="ccg-section-heading"><b>${esc(order.id)}</b><span class="ccg-badge">${status}</span></div>${list(order.items).map(i=>`<div class="ccg-order-item"><div><h3>${esc(i.name)}</h3><p>单价示例 ${money(i.priceCents)} · 数量 ${count(i.qty)}</p></div><strong>${money(valid(i.priceCents)&&valid(i.qty)&&valid(i.priceCents*i.qty)?i.priceCents*i.qty:null)}</strong></div>`).join('')||'<p>商品明细待核对</p>'}<p class="ccg-muted">共 ${count(totalQty(order.items))} 件</p><details><summary>订单金额与快照</summary><p>商品 ${money(order.subtotal)} − 优惠 ${money(order.discount)} + 演示运费 ${money(order.shipping)}</p><p>虚构演示地址快照：${esc(order.address?.name||'未填写')} · ${esc(order.address?.address||'未填写')}</p><p>演示推荐人：${esc(order.referrer||'未绑定')}</p><p>不显示不存在的下单时间或配送时效。</p></details><div class="ccg-section-heading"><span>${order.status==='pending'?'应付示例':'订单金额示例'}</span><strong class="ccg-price">${money(order.payable)}</strong></div><div class="ccg-actions">${actions}</div>${order.status==='paid'?'<p class="ccg-muted">待模拟发货；用户视图不提供商家发货操作。</p>':''}<details><summary>此订单模拟流水</summary>${list(s.ledger).filter(l=>l.orderId===order.id).map(l=>`<p>${esc(({payment:'模拟支付',refund:'模拟退款',commission:'推荐佣金入账',commission_reversal:'退款冲回佣金'})[l.type]||'未知流水')} ${Number.isSafeInteger(l.cents)?(l.cents<0?'−':'')+money(Math.abs(l.cents)):'金额待核对'}${l.beneficiary?' · 演示受益人 '+esc(l.beneficiary):''}</p>`).join('')||'<p>暂无模拟流水</p>'}</details></article>`;}
g.NutriCommerceCatalogOrdersGlassV1=Object.freeze({renderShop,renderOrders,orderCounts,buildId:'commerce-catalog-orders-glass-view-v1'});
})(typeof window!=='undefined'?window:globalThis);
